settings.custom_css:
selector{margin-top:34px;}
selector .elementor-tabs-wrapper { display:flex!important; flex-wrap:wrap; gap:12px; margin-bottom:22px; }
selector .elementor-tab-desktop-title { padding: 18px 26px !important; border-radius: 999px !important; background:#FFFFFF !important; border:0!important; box-shadow:0 10px 30px -18px rgba(9,23,31,.35); transition: background .3s ease, color .3s ease; }
selector .elementor-tab-desktop-title:hover { background:#DDEFF6 !important; }
selector .elementor-tab-desktop-title.elementor-active { background:#4AB7D5 !important; }
selector .elementor-tab-title, selector .elementor-tab-title a { color:#09171F !important; }
selector .elementor-tab-desktop-title::before, selector .elementor-tab-desktop-title::after { display:none!important; }
selector .elementor-tabs-content-wrapper { background:#FFFFFF !important; border-radius:28px !important; padding:56px !important; border:0!important; box-shadow:0 30px 70px -30px rgba(9,23,31,.3); }
selector .elementor-tab-content { border:0!important; }
selector .elementor-tab-mobile-title { color:#09171F!important; background:#EEF6FA!important; border-radius:14px; margin-bottom:8px; border:0!important; }
selector .elementor-tab-mobile-title.elementor-active { background:#4AB7D5!important; }
@media(max-width:767px){ selector .elementor-tabs-content-wrapper{ padding:24px !important; } }
